const RF_TreeNode *const TREES[TREE_N_TREES] = {
    tree0_nodes,  tree1_nodes,  tree2_nodes,  tree3_nodes,  tree4_nodes,
    tree5_nodes,  tree6_nodes,  tree7_nodes,  tree8_nodes,  tree9_nodes,
    tree10_nodes, tree11_nodes, tree12_nodes, tree13_nodes, tree14_nodes,
    tree15_nodes, tree16_nodes, tree17_nodes, tree18_nodes, tree19_nodes,
    tree20_nodes, tree21_nodes};

inline void treePredictSingle(const RF_TreeNode* nodes, const float* x, float* outProbs) {
  int node = 0;
  while (nodes[node].feature != -2) {
    if (x[nodes[node].feature] <= nodes[node].threshold) node = nodes[node].left;
    else node = nodes[node].right;
  }
  for (int c = 0; c < TREE_N_CLASSES; c++) {
    outProbs[c] = nodes[node].probs[c];
  }
}

inline void treeForestPredict(const float *x, float *outProbs) {
  float leaf[TREE_N_CLASSES];
  for (int c = 0; c < TREE_N_CLASSES; c++)
    outProbs[c] = 0.0f;
  for (int t = 0; t < TREE_N_TREES; t++) {
    treePredictSingle(TREES[t], x, leaf);
    for (int c = 0; c < TREE_N_CLASSES; c++)
      outProbs[c] += leaf[c];
  }
}
